  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-930-028$m$, NULL, $m$OFF Timing: Label Lc1$m$, NULL, NULL, NULL, NULL, $m$[-30 to 30/20/1]$m$),
