  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-930-031$m$, NULL, $m$Envelope Lc1$m$, NULL, NULL, NULL, NULL, $m$[0 to 20/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-930-032$m$, NULL, $m$OFF Timing: Envelope Lc1$m$, NULL, NULL, NULL, NULL, $m$[-30 to 30/20/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-940-001$m$, NULL, $m$Exposure Level Mode Tables$m$, NULL, NULL, NULL, $m$Determines if a blade bend prevention pattern is made when the ID sensor pattern is made. This setting controls the pattern count. DFU [0 to 100/0/1] Increase the setting if the rotation of the drum is not smooth, that is, when drum rotation is making noise. 2950 Vh Pattern Creation Setting DFU Appendix: Creates the Vh pattern (standard drum potential for half-tone) on the drum Service during process control. Program$m$, $m$[0 to 15/7/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-940-002$m$, NULL, $m$Offset Light Amount$m$, NULL, NULL, NULL, NULL, $m$[-100 to 0/-45/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-960$m$, NULL, $m$Process Interval DFU$m$, NULL, NULL, NULL, $m$[0 to 7/0/1 sec] 2961 Developer Adjust Mode DFU$m$, $m$[0 to 7/0/1 sec]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-962-001$m$, NULL, $m$Execute$m$, NULL, NULL, NULL, $m$Push [Execute] to execute the process control cycle manually. Note: This SP executes only if SP3901 is enabled. 2963 Installation Mode Use the keyboard display to enter the lot number of the developer. (The lot number is embossed on the top edge of the developer pack.) Press "Execute" to initialize the developer and force toner supply to the toner hopper at machine installation. Important: After you replace developer in a machine that has been already installed, do not use SP2963 to initialize the developer. Use SP2801 (TD Sensor Initial Setting) to initialize the TD sensor.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-962-002$m$, NULL, $m$Developer Lot Number Input$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-966$m$, NULL, $m$Drum Conditions: Periodic Adjustment$m$, NULL, NULL, NULL, $m$Sets the time interval between automatic adjustments. [1 to 24/24/1 hour]$m$, $m$[1 to 24/24/1 hour]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-967$m$, NULL, $m$Developer Density Adjustment Mode$m$, NULL, NULL, NULL, $m$Determines whether the amount of toner is checked during auto process control with only the TD sensor. With this feature on, the machine uses the TD sensor only. [0 to 1/0/1] 0: Off 1: On During auto process control execution after the main switch is turned on, the toner amount in the development unit is normally checked and adjusted using the ID sensor. However, in some environments, such as where there could be traces ammonia in the air, copies could appear dirty or too dark because the ID sensor reading is not reliable.$m$, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-968-001$m$, NULL, $m$Copy Count Setting Service Sets the standard number of copies by using the number of toner bottle Program rotations. DFU Mode Tables$m$, NULL, NULL, NULL, $m$Press Execute to force used toner into the toner collection bottle. The moving components of the cleaning and toner collection areas will rotate for about 60 sec. with the transfer belt released. 2969 Toner Bottle Revolution Count$m$, $m$[500 to 112/100/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-968-002$m$, NULL, $m$Count Reset Press "Execute" to reset the toner bottle rotation count. DFU$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-968-003$m$, NULL, $m$Copy Count Display Used to check the number of toner bottle rotations.$m$, NULL, NULL, NULL, NULL, $m$[0 to 0xFFFF/0/0]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP2-968-004$m$, NULL, $m$Copy Count History 1$m$, NULL, NULL, NULL, NULL, $m$[0 to 0xFFFF/0/0]$m$);
