  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP4-450-001$m$, NULL, $m$Black Subtraction ON/OFF Determines whether black subtraction is done. 0: Black subraction OFF 1: Black subtraction ON$m$, NULL, NULL, NULL, $m$This SP controls black subtraction and shading correction in scanned images.$m$, $m$[0 to 1/1/1]$m$),
