  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP4-996$m$, NULL, $m$White Paper Detect Level$m$, NULL, NULL, NULL, $m$Sets the detection level for blank paper. The higher the setting that you enter, the greater the sensitivity of detection. [0 to 6/3/1]$m$, $m$[0 to 6/3/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-024$m$, NULL, $m$mm/inch Display Selection$m$, NULL, NULL, NULL, $m$Selects whether mm or inches are used in the display. Note: After selecting the number, you must turn the main power switch off and on. Europe/Asia model: [0 = mm / 1 = inch] American model: [0 = mm / 1 = inch]$m$, $m$[0 = mm / 1 = inch] [0 = mm / 1 = inch]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-037$m$, NULL, $m$Status Lamp Mode Not Used$m$, NULL, NULL, NULL, $m$0: OFF / 1: ON$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-045$m$, NULL, $m$Accounting Counter$m$, NULL, NULL, NULL, $m$Selects the counting method if the meter charge mode is enabled with SP5-930-1. Note: You can change the setting only one time. [0 to 1/ 1] 0: Development counter. Shows the total counts for color (Y, M, C) and black (K). 1: Paper counter. Shows the total page counts for: Black Total, Black Copies, Black Prints.$m$, $m$[0 to 1/ 1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-055$m$, NULL, $m$Display IP Address$m$, NULL, NULL, NULL, $m$Switches the banner display of MFP device display on and off. [0 to 1 / 0 / 1] [OFF] ON$m$, $m$[0 to 1 / 0 / 1] [OFF]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-071$m$, NULL, $m$Set Bypass Paper Size Display$m$, NULL, NULL, NULL, $m$When this SP is enabled, a pop-up will appear and tell the operator whether the size of the paper in the bypass tray matches the size of the paper selected on the operation panel display. [0 to 1/0/1] 0:Disabled 1:Enables$m$, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-074-002$m$, NULL, $m$Home Screen Login Setting 91 (0:OFF 1:SDK 2:Reserve) Program 0:Disabled 1:SDK app 2:Legacy app (reserved) Mode Tables$m$, NULL, NULL, NULL, NULL, $m$[0 to 2/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-074-092$m$, NULL, $m$Product ID Enter the type of application registered under SP5075-1. This registers the SDK product ID or the legacy ID.$m$, NULL, NULL, NULL, NULL, NULL),
