  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-083$m$, NULL, $m$Toner End LED Blink Control$m$, NULL, NULL, NULL, $m$001 Sets whether the LED will blink or remain OFF at Toner End. [0 to 1/0/1] 0:LED Remains OFF 1:LED Blinks$m$, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-101$m$, NULL, $m$Warm-up Level Setting Not Used$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-112-002$m$, NULL, $m$0: None 1: Expansion Device 1 2: Expansion Device 2 3: Expansion Device 3$m$, NULL, NULL, NULL, $m$Determines whether a non-standard paper size can be input for the universal cassette trays (Tray 2, Tray 3) [0 to 1/1] 0: No 1: Yes. If "1" is selected, the customer will be able to input a non-standard paper size using the UP mode. 5113 Optional Counter Type Default Optional Counter Type Selects the type of counter: 0: None 1: Key Card (RK3, 4) 2: Key Card Down 1 3: Pre-paid Card 4: Coin Lock 5: MF Key Card 11: Exp Key Card (Add) 12: Exp Key Card (Deduct) Note: Items 1, 2, 3, 5, 5 are for Japan Only External Optional Counter Type Enables the SDK application. This lets you select a number for the external device for user access control. Note: "SDK" refers to software on an SD card.$m$, $m$[0 to 3/1]$m$);
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-114$m$, NULL, $m$Optional Counter I/F$m$, NULL, NULL, NULL, $m$This SP sets the machine for the MF Key Card Extension. 0: OFF, 1: ON$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-118$m$, NULL, $m$Disable Copying$m$, NULL, NULL, NULL, $m$Temporarily denies access to the machine. Japan Only Appendix: [0 to 1/1] Service 0: Release for normal operation Program 1: Prohibit access to machine Mode Clear Opt. Counter Removal Do not change. Japan Only [0 to 2/ 0 / 1] 0: Yes. Normal reset 1: Standby. Resets before job start/after completion 2: No. Normally no reset$m$, $m$[0 to 1/1] [0 to 2/ 0 / 1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-121$m$, NULL, $m$Counter Up Timing SSP$m$, NULL, NULL, NULL, $m$Determines whether the optional key counter counts up at paper feed-in or at paper exit. [0 to 1/1] 0: Feed count, 1: No feed count Set F-size Document$m$, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-126$m$, NULL, $m$Sets the original size that the machine detects for F sizes.$m$, NULL, NULL, NULL, $m$[0 to 2/1] 0: 8hf x 13 1: 8hf x 13qr 2: 8 x 13 Note: hf = 1/2, qr = 1/4$m$, $m$[0 to 2/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-001$m$, NULL, $m$A3T NA: Other:$m$, NULL, NULL, NULL, $m$This SP can be used to switch APS (Auto Paper Select) off when a coin lock or pre-paid key card device is connected to the machine. [0 to 1/1] 0: On, 1: Off 5129 F Paper Size Selection Sets the paper size that the machine detects when the 8 x 13 dial setting on a paper cassette is used (LT/DLT version). [0 to 2/1] 0: 8 x 13 1: 8hf x 13 2: 8qr x 13 Note: hf = 1/2, qr = 1/4 5131 Paper Size Type Selection Selects the paper size type (for originals and copy paper). (Only needs to be adjusted if the optional printer controller is installed) [0 to 3/1] 0: JP 1: NA 2: EU, AA, TWN, KOR 3: CH (China) After changing the value, turn the power switch off and on. 5150 Bypass Length Setting App. Switch Method Controls if the application screen is changed with a hardware switch or a 5162 software switch. [0 to 1/1] 0: Soft Key Set, 1: Hard Key Set 5165 Z-Fold Position Program Adjusts how paper is Z-folded. Note: In the notations below, "T" denotes "SEF". For example, "A3T" is "A3 Mode Tables SEF".$m$, $m$[2.5 to 25.4/2.5/1 mm] [2 to 25/2/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-002$m$, NULL, $m$B4T NA: Other:$m$, NULL, NULL, NULL, NULL, $m$[2.5 to 40.6/2.5/1 mm] [2 to 40/2/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-003$m$, NULL, $m$A4T NA: Other:$m$, NULL, NULL, NULL, NULL, $m$[2.5 to 10.2/2.5/1 mm] [2 to 10/2/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-004$m$, NULL, $m$DLTT NA: Other:$m$, NULL, NULL, NULL, NULL, $m$[2.5 to 20.3/2.5/1 mm] [2 to 20/2/ 1mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-005$m$, NULL, $m$LGT NA: Other:$m$, NULL, NULL, NULL, NULL, $m$[25. to 30.6/2.5/1 mm] [2 to 35/2/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-006$m$, NULL, $m$LTT NA: Other: 7 12x18 NA: Other:$m$, NULL, NULL, NULL, NULL, $m$[2.5 to 2.5/2.5/1 mm] [2 to 2/2/1 mm] [2.5 to 5.1/2.5/1 mm] [2 to 5/2/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-127-008$m$, NULL, $m$Other NA: Other: Fax Printing Mode at Optional Counter Off 5167 Determines the Fax print mode when the optional counter is off. 0: Print automatically. 1: Not do auto-print.$m$, NULL, NULL, NULL, NULL, $m$[2.5 to 2.5/2.5/ 1 mm] [2 to 2/2/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-169$m$, NULL, $m$CE Login$m$, NULL, NULL, NULL, $m$If you will change the printer bit switches, you must 'log in' to service mode with this SP before you go into the printer SP mode. [0 to 1/1] 0: Off. Printer bit switches cannot be adjusted. 1: On. Printer bit switches can be adjusted.$m$, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-179$m$, NULL, $m$By-pass tray paper size error display$m$, NULL, NULL, NULL, $m$Set the by-pass tray paper size error display to ON/OFF. 0: OFF / 1: ON$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-188$m$, NULL, $m$Copy NV Version$m$, NULL, NULL, NULL, $m$Copies NV version to another NVRAM. Note: NVRAM version management automatically initializes the NV for each machine.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-191$m$, NULL, $m$Mode Set$m$, NULL, NULL, NULL, $m$This setting determines whether the machine is allowed to move into energy save mode. 1: Allowed 0: Not allowed$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-195$m$, NULL, $m$Limitless SW$m$, NULL, NULL, NULL, $m$Selects the paper feed mode priority (productivity or tray). This is activated only Appendix: when a customer selects the "Auto paper Select". Service Productivity priority. Changes the feed station as soon as the machine Program detects the priority tray even the paper still remains in the current tray. Mode Tables Tray priority. This changes the feeding tray after the paper in the tray where the machine has been feeding paper has run out of paper. [0 to 1/0/1] 0: Productivity priority 1: Tray priority 5196 90 Degree Rotation (Copy)$m$, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-199-000$m$, NULL, $m$is center, minus is down, + is up. 5227 Page Numbering (Bates Stamp) 201 Allow Page No. Entry This SP specifies the number of digits to display for the entry of the starting page number. 202 Zero Surplus Setting This setting determines whether page numbers are prefixed with excess zeros when the number is smaller than the number of assigned digits. For example, with this setting on and 3 digits have been specified, the number "3" appears as "003". With this setting off, the number "3" will appear as a "3" without the zeros. 0:No zero surplus 1:Zero surplus allowed$m$, NULL, NULL, NULL, NULL, $m$[2 to 9/9/1] [0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-199-003$m$, NULL, $m$Duplex Printout Left/Right Position Horizontally positions the page numbers printed on both sides during duplexing.$m$, NULL, NULL, NULL, $m$Enables or disables feeding out of the finisher without stapling. [0: OFF] [1:ON] 0: OFF Paper feeds out with stapling at the maximum number of the finishing stapling when the machine gets a multiple printing job (over maximum number). 1: ON Paper feeds out without stapling at the maximum number of the finisher stapling when the machine gets a multiple printing job (over maximum number) 5212 Page Numbering$m$, $m$[-10 to +10/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-199-004$m$, NULL, $m$Duplex Printout High/Low Position Vertically positions the page numbers printed on both sides during duplexing.$m$, NULL, NULL, NULL, NULL, $m$[-10 to +10/1 mm]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-302-000$m$, NULL, $m$cannot be input, so the eight-digit setting for 002 or 003 becomes a seven-digit setting) 3rd Day of the week. 0: Sunday, 1: Monday The number of the week for the day selected at the 3rd digit. If "0" is selected for "Sunday", for example, and the selected 4th Sunday is the start of the 2nd week, then input a "2" for this digit. 5th, 6th The time when the change occurs (24-hour as hex code). Example: 00:00 (Midnight) = 00, 01:00 (1 a.m.) = 01, and so on. 7th The number of hours to change the time. 1 hour: 1 If the time change is not a whole number (1.5 hours for 8th example), digit 8 should be 3 (30 minutes).$m$, NULL, NULL, NULL, $m$Sets the time clock for the local time. This setting is done at the factory before Appendix: delivery. The setting is GMT expressed in minutes. Service [-1440 to 1440/1 min.] Program JA: +540 (Tokyo) NA: -300 (NY) Mode Tables EU: +6- (Paris) CH: +480 (Peking) TW: +480 (Taipei) AS: +480 (Hong Kong) Summer Time Lets you set the machine to adjust its date and time automatically with the change to Daylight Savings time in the spring and back to normal time in the fall. This SP lets you set these items: Day and time to go forward automatically in April. Day and time to go back automatically in October. Set the length of time to go forward and back automatically. The settings for 002 and 003 are done with 8-digit numbers: Digits Meaning 5307 1st, 2nd Month. 4: April, 10: October (for months 1 to 9, the first digit of$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-302-001$m$, NULL, $m$Setting Enables/disables the settings for 002 and 003. 0: Disable, 1: Enable$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-302-003$m$, NULL, $m$Rule Set (Start) The start of summer time.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-302-004$m$, NULL, $m$Rule Set (End) The end of summer time. Access Control DFU$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-401$m$, NULL, $m$This SP adjusts the settings below when installing and SDK application.$m$, NULL, NULL, NULL, $m$Note: "SDK" is the "Software Development Kit". This data can be converted from SAS (VAS) when installed or uninstalled. 103 Default Document ACL Used to assign the default access user access privileges to their own documents on the document server. 104 Authentication Time Standard setting "0" equals 60 sec. [0 to 255/0/1 sec.] 162 Extend Certification Detail Logout without an IC card. [0 to 1/0/1] 0: Not allowed (default) 1: Allowed 200 SDK1 Unique ID 201 SDK1 Certification Method 210 SDK2 Unique ID 211 SDK2 Certification Method 220 SDK3 Unique ID 221 SDK3 Certification Method 230 SDK(Type TF) Unique ID 240 Detail Option: Unique ID$m$, $m$[0 to 255/0/1 sec.] [0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-402$m$, NULL, $m$Access Control Not Used$m$, NULL, NULL, NULL, $m$101-170 SDJK1 Limit Settings$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-404-001$m$, NULL, $m$System Log Disp Determines whether an error code appears in the system log after a user authentication failure occurs. 0: Off, 1: On$m$, NULL, NULL, NULL, NULL, $m$[0 or 1/ 0 /1]$m$),
